import React from 'react';

// إذا كنت تستخدم مكونات Font Awesome React:
// import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
// import { faLightbulb, faChartLine, faUsers } from '@fortawesome/free-solid-svg-icons';

const Features = () => {
  return (
    <section id="how-it-works" className="bg-light-grey py-16 md:py-20">
      <div className="container mx-auto px-4 text-center">
        <h2 className="text-3xl md:text-4xl font-bold text-primary-blue mb-12">
          اكتشف كيف يمكن لـ Stag.io تحويل مسارك المهني
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 lg:gap-12">
          {/* بطاقة الميزة 1 */}
          <div className="feature-card bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300">
            {/* استخدام وسم <i> بسيط لـ Font Awesome للاختصار. لتطبيقات React، استخدم مكون FontAwesomeIcon. */}
            <i className="fas fa-lightbulb text-5xl text-primary-blue mb-4"></i>
            {/* <FontAwesomeIcon icon={faLightbulb} className="text-5xl text-primary-blue mb-4" /> */}
            <h3 className="text-xl font-semibold text-text-grey mb-3">تطابق ذكي للفرص</h3>
            <p className="text-base text-gray-600">
              نستخدم خوارزميات متقدمة لربطك بأكثر الفرص التدريبية ملاءمة لمهاراتك وطموحاتك المهنية.
            </p>
          </div>

          {/* بطاقة الميزة 2 */}
          <div className="feature-card bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300">
            <i className="fas fa-chart-line text-5xl text-primary-blue mb-4"></i>
            {/* <FontAwesomeIcon icon={faChartLine} className="text-5xl text-primary-blue mb-4" /> */}
            <h3 className="text-xl font-semibold text-text-grey mb-3">إدارة سهلة للتقدم</h3>
            <p className="text-base text-gray-600">
              تتبع طلباتك ومقابلاتك وتواصل مع الشركات بسهولة من لوحة تحكم واحدة مبسطة.
            </p>
          </div>

          {/* بطاقة الميزة 3 */}
          <div className="feature-card bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300">
            <i className="fas fa-users text-5xl text-primary-blue mb-4"></i>
            {/* <FontAwesomeIcon icon={faUsers} className="text-5xl text-primary-blue mb-4" /> */}
            <h3 className="text-xl font-semibold text-text-grey mb-3">شبكة واسعة من الشركات</h3>
            <p className="text-base text-gray-600">
              وصول إلى شبكة متنامية من الشركات الرائدة التي تبحث عن مواهب طلابية مثلك تمامًا.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Features;
